import{_ as t,o,c as s,a2 as a}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"端到端测试套件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/e2e-suites.md","filePath":"zh/dev/e2e-suites.md"}'),d={name:"zh/dev/e2e-suites.md"};function r(c,e,i,n,l,p){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="端到端测试套件" tabindex="-1">端到端测试套件 <a class="header-anchor" href="#端到端测试套件" aria-label="Permalink to &quot;端到端测试套件&quot;">​</a></h1><p>门住发布的深度测试。全部经串口控制台驱动真实 QEMU 启动；下面是 2.1.0 矩阵——发布证据引用的是真实输出（申报 skip 数）。</p><h2 id="_2-1-0-验证矩阵" tabindex="-1">2.1.0 验证矩阵 <a class="header-anchor" href="#_2-1-0-验证矩阵" aria-label="Permalink to &quot;2.1.0 验证矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>门</th><th>工具</th></tr></thead><tbody><tr><td>1</td><td>Host 单测（<code>make test</code>）</td><td><code>tools/run_host_tests.py</code></td></tr><tr><td>2</td><td>看门狗/日志/健康 E2E</td><td><code>tools/wp12_watchdog_logging_e2e.py</code></td></tr><tr><td>3</td><td>TUI 命令面 E2E</td><td><code>tools/wp10_tui_e2e.py</code></td></tr><tr><td>4</td><td>中文控制台 E2E</td><td><code>tools/wp10_chinese_e2e.py</code></td></tr><tr><td>5</td><td>TUI 桌面应用 E2E</td><td><code>tools/wp10_tuiqa_apps_e2e.py</code></td></tr><tr><td>6</td><td>原生桌面 E2E</td><td><code>tools/wp10_native_e2e.py</code></td></tr><tr><td>7</td><td>L1 逐应用记录（2.1.0）</td><td>从 ush 经 <code>run</code> 执行每个 <code>l1apps/</code> 程序，一应用一行记录</td></tr></tbody></table><h2 id="host-单测-tools-run-host-tests-py" tabindex="-1">Host 单测 - tools/run_host_tests.py <a class="header-anchor" href="#host-单测-tools-run-host-tests-py" aria-label="Permalink to &quot;Host 单测 - tools/run_host_tests.py&quot;">​</a></h2><p>19 个测试宿主侧编译 L0 组件并运行：multiboot2 解析器、密码学 （BN/EC/RSA/X.509/AEAD/X25519）、TLS 1.3 密钥调度、TCP 拥塞控制、 块层 512 门、SCSI、红外、摄像头、wifi、蓝牙……无 openssl fixture 时 <strong>17 PASS + 2 SKIP-FIXTURE</strong>（rsa/x509；fixture 齐备时真跑——如实 申报当时的状态）。</p><h2 id="看门狗-日志-健康-e2e-tools-wp12-watchdog-logging-e2e-py" tabindex="-1">看门狗/日志/健康 E2E - tools/wp12_watchdog_logging_e2e.py <a class="header-anchor" href="#看门狗-日志-健康-e2e-tools-wp12-watchdog-logging-e2e-py" aria-label="Permalink to &quot;看门狗/日志/健康 E2E - tools/wp12_watchdog_logging_e2e.py&quot;">​</a></h2><p>14 个场景（S1-S14）。最重要的两个：</p><ul><li><strong>S12（Intel TCO）</strong>：q35 + <code>-no-reboot</code>；断言 TCO 发现行 （<code>Intel TCO found: PMBASE=... TCOBASE=...</code>）、武装看门狗、饿死 它、断言真实复位与第二次启动。</li><li><strong>S13（ACPI WDAT）</strong>：同一形态，走 WDAT 表项。</li></ul><p>另含 klog 写/冲/轮转/过滤链（阈值 4096 -&gt; 实际生成 <code>kernel.log</code> + <code>kernel.log.1</code>）、看门狗策略击杀（饿死任务被杀并留日志、内核存活）、 健康（JSON 导出合法性、3-spinner CPU 告警 <code>CPU-LOCKED</code> 且内核 存活）。</p><h2 id="tui-中文-桌面应用-原生套件" tabindex="-1">TUI / 中文 / 桌面应用 / 原生套件 <a class="header-anchor" href="#tui-中文-桌面应用-原生套件" aria-label="Permalink to &quot;TUI / 中文 / 桌面应用 / 原生套件&quot;">​</a></h2><p><code>tools/wp10_tui_e2e.py</code> 从 <code>oc&gt;</code> 驱动 L0 TUI 命令面； <code>tools/wp10_chinese_e2e.py</code> 驱动 CJK 控制台；tuiqa/native 套件从 Ring-3 的 <code>ush&gt;</code> 提示符起步驱动桌面应用（文件/编辑器/面板/终端 + 原生编辑器/文件管理器升级）——2.x 启动流适配。</p><h2 id="l1-逐应用记录-2-1-0-新增" tabindex="-1">L1 逐应用记录（2.1.0 新增） <a class="header-anchor" href="#l1-逐应用记录-2-1-0-新增" aria-label="Permalink to &quot;L1 逐应用记录（2.1.0 新增）&quot;">​</a></h2><p>正式 L1 应用集小而诚实：<strong>ush</strong>（唯一的 <code>OC_L1_APP_DECL</code> 应用）加 <code>l1apps/</code> 的 36 个嵌入测试程序。逐应用记录启动发布 ISO、从 ush 经 <code>run &lt;名字&gt;</code> 启动每个程序并记录观察到的输出。证据与套件日志一起放 在 <code>evidence/</code>。</p><h2 id="回归电池-v1-时代-参考-tools-run-fix4-regression-py" tabindex="-1">回归电池（v1 时代，参考）- tools/run_fix4_regression.py <a class="header-anchor" href="#回归电池-v1-时代-参考-tools-run-fix4-regression-py" aria-label="Permalink to &quot;回归电池（v1 时代，参考）- tools/run_fix4_regression.py&quot;">​</a></h2><p>1.0.0 时代的 28 项检查：启动横幅、启动完成、异常自测 3/3、命令计数 233（v1 单提示符世界）、uname tag 形态、heaptest、fstest、 cryptotest、crashlog、l1test、以及每个 <code>run &lt;userprog&gt;</code>。其命令 计数与提示符流断言早于 v2 的 Ring-3 拆分——保留作参考，其 <code>run &lt;userprog&gt;</code> 部分由 L1 逐应用记录覆盖。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 tools/run_fix4_regression.py build/opencube.iso out.log</span></span></code></pre></div><h2 id="ssh-https-套件-可用-非常规门" tabindex="-1">SSH / HTTPS 套件（可用，非常规门） <a class="header-anchor" href="#ssh-https-套件-可用-非常规门" aria-label="Permalink to &quot;SSH / HTTPS 套件（可用，非常规门）&quot;">​</a></h2><p><code>tools/ssh_mainstream_test.py</code> + <code>tools/sshd_test.py</code>（paramiko 客户 端对访客内 sshd，主机密钥经 <code>host_keygen_etc</code> 种到 /etc）与 <code>tools/run_fix4_https_e2e.py</code>（对 <code>tools/https_test_server.py</code>）。 需要种好的 <code>etc.img</code>（<code>make etc.img</code>）与网络 fixture；动网络栈时 跑它们。</p><h2 id="etc-卷-fixture" tabindex="-1">/etc 卷 fixture <a class="header-anchor" href="#etc-卷-fixture" aria-label="Permalink to &quot;/etc 卷 fixture&quot;">​</a></h2><p>SSH 与 HTTPS 套件假设有种好的 <code>etc.img</code>。每个测试周期构建一次：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make etc.img          # 32 MiB FAT32 + opencube.conf</span></span>
<span class="line"><span># 然后首次启动后：host_keygen_etc（写 SSH 密钥）</span></span></code></pre></div><p>QEMU 的 <code>run-*</code> make 目标会自动挂上它。</p>`,23)])])}const _=t(d,[["render",r]]);export{u as __pageData,_ as default};
